from lib import *
S = SS('w61')
steps = [
    step("先算带宽时延积(BDP)。测试链路:netlab 限速 100 Mbit/s,每方向延迟 50 ms,往返 100 ms。BDP = 12,500,000 字节/秒 × 0.1 秒 = 1,250,000 字节,约 1.19 MiB(1221 KiB):要让管道始终是满的,在路上的字节数必须达到这个量,接收窗口至少这么大。窗口 ÷ RTT 是吞吐上限(计算):窗口 64 KiB → 0.7 MB/s;256 KiB → 2.6 MB/s;512 KiB → 5.2 MB/s;1024 KiB → 10.5 MB/s;2048 KiB 起已经超过链路的 12.5 MB/s,封顶在带宽上。", t=tl(S(1)), mark=lidx(S(1), 'BDP = 12,500,000', '接收窗口  1024 KiB'), done=lidx(S(1), '接收窗口    64 KiB', '接收窗口   256 KiB', '接收窗口   512 KiB', '接收窗口  2048 KiB', '接收窗口  4096 KiB'), b=bars([['窗口 256 KiB', 2.6, '2.6 MB/s'], ['窗口 512 KiB', 5.2, '5.2 MB/s'], ['窗口 1024 KiB', 10.5, '10.5 MB/s'], ['链路上限', 12.5, '12.5 MB/s']], 12.5, mark=[2], done=[0, 1, 3]), kv=KV([['带宽', '100 Mbit/s = 12.5 MB/s'], ['RTT', '100 ms'], ['BDP', '1,250,000 字节 ≈ 1221 KiB'], ['吞吐上限', 'min(窗口 ÷ RTT, 带宽)']], ['BDP'])),
    step("实测:接收方在 connect 之前设置 SO_RCVBUF,发送 6 秒,取第 2~5.5 秒的平均吞吐。256 KiB → 2.53 MB/s(计算 2.62);512 KiB → 4.98 MB/s(计算 5.24);1024 KiB → 9.91 MB/s(计算 10.49);2048 KiB → 12.46 MB/s;4096 KiB → 12.46 MB/s,后两个都顶在 12.5 MB/s 的带宽上。窗口小于 BDP 时吞吐被窗口卡住,和窗口 ÷ RTT 吻合(略低几个百分点),够大之后封顶在带宽上。64 KiB 是个例外:读回值是 64 KiB,但实测 2.52 MB/s,不是计算的 0.66 MB/s,对端窗口 snd_wnd 303 KiB——小于约 256 KiB 的 SO_RCVBUF 在 macOS 上不被照办,实际窗口按 256 KiB 左右算(和 w49 的发现一致)。不设置 SO_RCVBUF 时(自动调整),吞吐 10.44 MB/s,对端窗口 snd_wnd 到了 4095 KiB;读回的 128 KiB 只是初始值,不代表实际窗口。", t=tl(S(2)), mark=lidx(S(2), '64 KiB ', '不设置(自动调整)'), done=lidx(S(2), '256 KiB ', '512 KiB ', '1024 KiB ', '2048 KiB ', '4096 KiB '), b=bars([['64 KiB(实际按 256 KiB)', 2.52, '2.52 MB/s'], ['256 KiB', 2.53, '2.53 MB/s'], ['512 KiB', 4.98, '4.98 MB/s'], ['1024 KiB', 9.91, '9.91 MB/s'], ['2048 KiB', 12.46, '12.46 MB/s'], ['4096 KiB', 12.46, '12.46 MB/s'], ['自动调整', 10.44, '10.44 MB/s']], 12.5, mark=[0], done=[1, 2, 3, 4, 5, 6]), kv=KV([['窗口 < BDP', '吞吐 ≈ 窗口 ÷ RTT'], ['窗口 ≥ BDP', '封顶在 12.46 MB/s(带宽)'], ['SO_RCVBUF 64 KiB', '读回 64 KiB,实际吞吐按 ~256 KiB'], ['自动调整', '10.44 MB/s']], ['窗口 < BDP'])),
    step("缓冲过大的代价:窗口远大于 BDP 时,多出来的字节排在限速链路的队列里,往返时间变长(bufferbloat)。看第二节的 srtt 列:SO_RCVBUF 512 KiB 和 1024 KiB 时是 104 / 105 ms(接近链路自身的 100 ms);2048 KiB 时 168 ms;4096 KiB 时 197 ms;自动调整时 177 ms。吞吐一样是 12.46 MB/s,但延迟涨了将近一倍。对照:同样 100 ms RTT、没有带宽限制的链路上,SO_RCVBUF 256 KiB → 2.60 MB/s、srtt 102 ms;SO_RCVBUF 4096 KiB → 41.54 MB/s、srtt 101 ms——没有瓶颈带宽就没有队列,srtt 不变,吞吐按窗口 ÷ RTT 一路涨。", t=tl(S(3)), mark=lidx(S(3), '无限速:SO_RCVBUF 256 KiB', '无限速:SO_RCVBUF 4096 KiB'), done=lidx(S(3), '无限速:SO_RCVBUF 256 KiB'), b=bars([['1024 KiB 缓冲 srtt', 105, '105 ms'], ['2048 KiB 缓冲 srtt', 168, '168 ms'], ['4096 KiB 缓冲 srtt', 197, '197 ms'], ['无限速 4096 KiB srtt', 101, '101 ms']], 200, mark=[2], done=[0, 1, 3]), kv=KV([['有瓶颈带宽 + 大缓冲', 'srtt 168~197 ms(排队)'], ['无瓶颈带宽 + 大缓冲', 'srtt 101 ms,吞吐 41.54 MB/s'], ['含义', '多余的窗口只会排队']], ['含义'])),
    step("发送缓冲区(SO_SNDBUF)同样限制:接收缓冲区固定 4 MiB,发送方 accept 之后设置不同的 SO_SNDBUF。64 KiB → 0.63 MB/s(就是计算的 0.66 MB/s,这次小缓冲被照办了);256 KiB → 2.51 MB/s;1024 KiB → 9.97 MB/s;4096 KiB → 12.46 MB/s(srtt 198 ms,又出现排队)。和接收缓冲区不同,发送缓冲区在 64 KiB 这么小时仍然按设置值生效。结论:吞吐 ≈ min(发送缓冲, 接收窗口, 拥塞窗口) ÷ RTT,再被带宽封顶;管道要填满,两端的缓冲区都至少要有 BDP 那么大,但再大只会排队。", t=tl(S(4)), mark=lidx(S(4), '64 KiB ', '4096 KiB '), done=lidx(S(4), '256 KiB ', '1024 KiB '), b=bars([['SO_SNDBUF 64 KiB', 0.63, '0.63 MB/s'], ['256 KiB', 2.51, '2.51 MB/s'], ['1024 KiB', 9.97, '9.97 MB/s'], ['4096 KiB', 12.46, '12.46 MB/s']], 12.5, mark=[0], done=[1, 2, 3]), kv=KV([['发送缓冲 64 KiB', '0.63 MB/s(= 计算值)'], ['发送缓冲 ≥ BDP', '12.46 MB/s'], ['吞吐', 'min(发送缓冲, 接收窗口, cwnd) ÷ RTT']], ['吞吐'])),
]
A = mkartw('w61', 61, '网络协议,TCP,带宽时延积,BDP,SO_RCVBUF,SO_SNDBUF,bufferbloat,真实验证,动画演示',
    '在 100 Mbit/s、RTT 100 ms 的 netlab 链路上扫描缓冲区:BDP 是 1,250,000 字节;接收窗口 256/512/1024 KiB 吞吐 2.53/4.98/9.91 MB/s,2048 KiB 起封顶 12.46 MB/s;过大的缓冲让 srtt 从 105 ms 涨到 197 ms;发送缓冲 64 KiB 只有 0.63 MB/s。',
    '“长肥管道”(带宽大、延迟高)为什么常常跑不满?答案在带宽时延积:窗口小于 BDP,管道里就有空洞。这篇用 netlab 造一条 100 Mbit/s、RTT 100 ms 的链路,把接收缓冲区和发送缓冲区从小到大扫一遍,量吞吐,也量缓冲过大造成的排队延迟。',
    [('1,250,000 字节', '100 Mbit/s × 100 ms 的带宽时延积'), ('9.91 → 12.46 MB/s', '接收缓冲区从 1024 KiB 增加到 2048 KiB:吞吐封顶在链路带宽'), ('105 → 197 ms', '接收缓冲区从 1024 KiB 增加到 4096 KiB 时的 srtt:多出来的窗口只是排队')],
    [('BDP', '<p>BDP = 带宽 × RTT,是让管道始终满的在途字节数。窗口 ÷ RTT 给出窗口受限时的吞吐上限。</p>'),
     ('窗口受限', '<p>接收缓冲区小于 BDP 时,实测吞吐和窗口 ÷ RTT 吻合;大于 BDP 后封顶在带宽上。小于约 256 KiB 的 SO_RCVBUF 在 macOS 上不被照办。</p>'),
     ('缓冲过大', '<p>窗口超过 BDP 的部分不会提高吞吐,只会在瓶颈队列里排队,srtt 从 105 ms 涨到 197 ms。没有带宽瓶颈时不排队。</p>'),
     ('发送缓冲区', '<p>SO_SNDBUF 同样限制吞吐,小到 64 KiB 也照办(0.63 MB/s)。两端都要有至少 BDP 的缓冲。</p>')],
    steps,
    [ENV_W + '。全部在 lo0 上,netlab 限速 100 Mbit/s、每方向延迟 50 ms(队列 100 个包),发送与接收在同一个进程的两个线程里;每个设置只传一次 6 秒,取 2~5.5 秒的平均,没有重复多次',
     '没有验证:真实广域网上的 BDP;小于 256 KiB 的 SO_RCVBUF 实际生效的值(只能从吞吐反推);自动调整缓冲区的上限由什么决定;队列管理算法(AQM、ECN)对 bufferbloat 的缓解;不同拥塞算法(BBR)下缓冲区的影响'],
    '带宽时延积与缓冲区')
